def prod_signs(arr):
    if not arr:
        return None

    sum_abs = sum(abs(num) for num in arr)

    sign_product = 1
    for num in arr:
        if num > 0:
            sign_product *= 1
        elif num < 0:
            sign_product *= -1
        else:
            sign_product *= 0

    return sum_abs * sign_product

